p.write_text('def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    if any(3 in row for row in grid):
        c = next(j for j in range(w) if any(row[j] == 3 for row in grid))
        for i in range(h):
            for j in range(w):
                if grid[i][j] == 3:
                    src = 2*c-j-1
                    if 0 <= src < w: out[i][j] = grid[i][src]
                    else: out[i][j] = 0
    else:
        r = next(i for i,row in enumerate(grid) if 3 in row)
        for i in range(h):
            for j in range(w):
                if grid[i][j] == 3:
                    src = 2*r-i-1
                    if 0 <= src < h: out[i][j] = grid[src][j]
                    else: out[i][j] = 0
    return out
